_FILE = "nanoGPT/depth_allocator.py"

_CONTENT = 'class DepthAllocator(nn.Module):
    """Hidden-state-difference exit (Ouro, arXiv:2510.25741, Sec. 5.4.1: exit
    when the change between consecutive recurrent states falls below a
    threshold), in the relative form ||h_t - h_{t-1}|| / ||h_t|| (the same
    form as the 'latent-diff' criterion in Huginn's released code,
    seal-rg/recurrent-pretraining recpre/raven_modeling_minimal.py:2149-2164;
    Huginn's paper criterion, Geiping et al. arXiv:2502.05171 Sec. 6.1, is the
    KL divergence between successive steps' outputs -- a different rule, not
    this arm).  Training-free.  The threshold is calibrated to the budget.
    The first comparison is after step 2 (the input of step 1 is the
    embedding, not a loop state), i.e. minimum depth 2."""

    R_MIN = 2

    def __init__(self, spec):
        super().__init__()
        self.register_buffer("delta", torch.zeros(()))    # = log(threshold)

    def train_step(self, lm, ids, progress):
        return None

    def configure_optimizer(self):
        return torch.optim.AdamW(self.parameters(), lr=1e-3)

    @staticmethod
    def _log_diff(cur, prev):
        cur, prev = cur.float(), prev.float()
        return torch.log((cur - prev).norm(dim=-1) / cur.norm(dim=-1).clamp_min(1e-6) + 1e-12)

    def _full_scores(self, d):
        s = d["states"]
        first = torch.full_like(s[0, :, 0], 1e9, dtype=torch.float32)
        return torch.stack([first, self._log_diff(s[1], s[0]), self._log_diff(s[2], s[1])], 0)

    def decide(self, step, feats):
        if step < self.R_MIN:
            return torch.ones(feats.h.shape[0], dtype=torch.bool, device=feats.h.device)
        st = feats.states
        return self._log_diff(st[step - 1], st[step - 2]) > self.delta

    def calibrate(self, calib, budget):
        self._calibrate_offset(calib, budget)

    # ---- shared calibration: one offset on a per-step "continue" score -------
    TARGET = 0.99            # calibrated realised mean, as a fraction of the budget

    def _sim(self, S, delta):
